def copyright_pages():
 return {
  "idolmaster_2":["[b]The Idolmaster 2[/b] (アイドルマスター2) is the second main 765 Production game in [[idolmaster_(classic)]]. It was released for Xbox 360 in 2011, followed by an expanded PlayStation 3 version.","","As the previous article noted, the returning idols are slightly older and use redesigned appearances. The story also introduces Jupiter, a male idol unit managed by 961 Production.","[h2]Characters[/h2]","The 765PRO cast is indexed under the 2005 group in [[List_of_Idolmaster_characters]].","","Jupiter:","* [[amagase_touma]]","* [[ijuuin_hokuto]]","* [[mitarai_shouta]]","[h2]Related tags[/h2]","* [[idolmaster]]","* [[idolmaster_(classic)]]","* [[idolmaster_1]]","* [[idolmaster_sp]]","[h2]External links[/h2]","* Official franchise portal: https://idolmaster-official.jp/"],
  "idolmaster_dearly_stars":["[b]The Idolmaster: Dearly Stars[/b] is a 2009 Nintendo DS game and branch of [[idolmaster]]. It tells its story from the idols' viewpoints as three newcomers join 876 Production and pursue their debuts with help from established idols.","","This expands the earlier article's description and retains its original four-character roster.","[h2]Characters[/h2]","* [[hidaka_ai]]","* [[mizutani_eri]]","* [[akizuki_ryou]]","* [[sakurai_yumeko]]","[h2]Related tags[/h2]","* [[idolmaster]]","* [[idolmaster_(classic)]]","* [[List_of_Idolmaster_characters]]","[h2]External links[/h2]","* Official franchise portal: https://idolmaster-official.jp/"],
  "idolmaster_cinderella_girls":["[b]The Idolmaster Cinderella Girls[/b] is a branch of [[idolmaster]] launched as a Mobage social game in 2011. The original game let producers recruit, train and compete with a cast divided into Cute, Cool and Passion attributes.","","The previous wiki documented more than 100 idols individually. The cast later grew further and expanded into animation, music, manga, live concerts and additional games. The original social game's service ended on March 30, 2023, but Cinderella Girls continues as a multimedia brand.","[h2]Major derived works[/h2]","* [[idolmaster_cinderella_girls_starlight_stage]] - rhythm and idol-training game launched in 2015.","* [[idolmaster_cinderella_girls_u149]] - manga and television anime centered on younger idols.","[h2]Characters[/h2]","See the 2011 group in [[List_of_Idolmaster_characters]].","[h2]Common units[/h2]","* [[new_generations]]","* [[triad_primus]]","* [[positive_passion]]","* [[pink_check_school]]","* [[lipps_(idolmaster)]]","* [[individuals]]","[h2]Related tags[/h2]","* [[idolmaster]]","* [[cygames]]","* [[cinderella_girls_card_parody]]","[h2]External links[/h2]","* Official Cinderella Girls library: https://cinderella-library.idolmaster-official.jp/","* Official record of the original game's closure: https://cinderella-library.idolmaster-official.jp/history/detail/?p=20230330_1"],
  "idolmaster_cinderella_girls_starlight_stage":["[b]The Idolmaster Cinderella Girls: Starlight Stage[/b] (デレステ) is a free-to-play rhythm and idol-training game derived from [[idolmaster_cinderella_girls]]. It was co-developed by Cygames and Bandai Namco Entertainment and released for Android and iOS in September 2015.","","As recorded by the previous article, it combines collectible cards with rhythm gameplay and 3D performances. It reuses and expands cards, songs and characters from the original social game while adding original material. Its producer works at 346 Production, with [[executive_mishiro]] as executive director in the anime-derived setting.","[h2]Selected songs and units[/h2]","* [[tulip_(idolmaster)]] - [[lipps_(idolmaster)]]","* [[love_letter_(idolmaster)]] - [[pink_check_school]]","* [[seizon_honnou_valkyria_(idolmaster)]]","* [[positive_passion]]","* [[triad_primus]]","* [[individuals]]","[h2]Selected costumes[/h2]","* [[starry_sky_bright_(idolmaster)]]","* [[across_the_stars_(idolmaster)]]","* [[showtime_illusion_(idolmaster)]]","* [[next_frontier_(idolmaster)]]","[h2]Related tags[/h2]","* [[idolmaster]]","* [[idolmaster_cinderella_girls]]","* [[cinderella_girls_card_parody]]","[h2]External links[/h2]","* Official site: https://cinderella.idolmaster.jp/sl-stage/"],
  "idolmaster_cinderella_girls_u149":["[b]The Idolmaster Cinderella Girls U149[/b] is a manga and 2023 television anime spin-off of [[idolmaster_cinderella_girls]]. It follows idols under 149 centimeters tall working with a young producer in the Third Entertainment Division.","[h2]Characters[/h2]","* [[tachibana_arisu]]","* [[sakurai_momoka]]","* [[akagi_miria]]","* [[ryuuzaki_kaoru]]","* [[sasaki_chie]]","* [[ichihara_nina]]","* [[matoba_risa]]","* [[yuuki_haru]]","* [[koga_koharu]]","[h2]Related tags[/h2]","* [[idolmaster]]","* [[idolmaster_cinderella_girls]]","* [[idolmaster_cinderella_girls_starlight_stage]]","[h2]External links[/h2]","* Official anime site: https://cinderella-u149-anime.idolmaster-official.jp/"],
  "idolmaster_million_live!":["[b]The Idolmaster Million Live![/b] is a 2013 branch of [[idolmaster]] centered on the 765 Pro Live Theater. It combines the 13 members of 765PRO ALLSTARS with 39 newer idols known collectively as MILLIONSTARS.","[h2]Games and adaptations[/h2]","* [[idolmaster_million_live!_theater_days]] - rhythm and idol-training game launched in 2017.","* [[idolmaster_million_live!_(anime)]] - 2023 television anime.","[h2]Characters[/h2]","See the 2013 group in [[List_of_Idolmaster_characters]].","[h2]Related tags[/h2]","* [[idolmaster]]","* [[idolmaster_(classic)]]","[h2]External links[/h2]","* Official portal: https://millionlive.idolmaster.jp/","* Official idol directory: https://millionlive-theaterdays.idolmaster-official.jp/idol/"],
  "idolmaster_million_live!_theater_days":["[b]The Idolmaster Million Live! Theater Days[/b] (ミリシタ) is a free-to-play rhythm and idol-training game in the [[idolmaster_million_live!]] branch. It launched for Android and iOS in June 2017 and depicts activities at the 765 Pro Live Theater.","[h2]Characters[/h2]","The game features 765PRO ALLSTARS and MILLIONSTARS; see [[List_of_Idolmaster_characters]].","[h2]Related tags[/h2]","* [[idolmaster]]","* [[idolmaster_million_live!]]","* [[idolmaster_million_live!_(anime)]]","[h2]External links[/h2]","* Official site: https://millionlive-theaterdays.idolmaster-official.jp/"],
  "idolmaster_side-m":["[b]The Idolmaster SideM[/b] is the male-idol branch of [[idolmaster]]. Launched in 2014, it follows former professionals and other aspiring performers who join 315 Production under the slogan that they became idols for a reason.","[h2]Games and adaptations[/h2]","* [[idolmaster_side-m_live_on_stage!]]","* [[idolmaster_side-m_growing_stars]]","* Television anime and stage adaptations normally use [[idolmaster_side-m]] together with any applicable medium tag.","[h2]Characters[/h2]","See the 2014 group in [[List_of_Idolmaster_characters]].","[h2]Related tags[/h2]","* [[idolmaster]]","[h2]External links[/h2]","* Official SideM portal: https://idolmaster-official.jp/sidem"],
  "idolmaster_side-m_growing_stars":["[b]The Idolmaster SideM: Growing Stars[/b] was a rhythm and story game in the [[idolmaster_side-m]] branch. It introduced the C.FIRST unit while retaining the broader 315 Production cast.","[h2]Characters[/h2]","See the SideM group in [[List_of_Idolmaster_characters]], including C.FIRST members [[amamine_shuu]], [[hanazono_momohito]] and [[mayumi_eishin]].","[h2]Related tags[/h2]","* [[idolmaster]]","* [[idolmaster_side-m]]","[h2]External links[/h2]","* Official SideM portal: https://idolmaster-official.jp/sidem"],
  "idolmaster_shiny_colors":["[b]The Idolmaster Shiny Colors[/b] is a branch of [[idolmaster]] launched in April 2018. The producer works with the idols of 283 Production. The brand includes games, music, comics, live performances and television animation.","[h2]Games and adaptations[/h2]","* The original browser-based production game is represented by [[idolmaster_shiny_colors]].","* [[idolmaster_shiny_colors_song_for_prism]] - 3D rhythm and training game.","* The television anime and its second season normally use [[idolmaster_shiny_colors]].","[h2]Characters and units[/h2]","See the Shiny Colors groups in [[List_of_Idolmaster_characters]].","[h2]Related tags[/h2]","* [[idolmaster]]","[h2]External links[/h2]","* Official site: https://shinycolors.idolmaster.jp/","* Official franchise overview: https://campaign-shinycolors-song-for-prism.idolmaster-official.jp/283prostyle/"],
  "idolmaster_shiny_colors_song_for_prism":["[b]The Idolmaster Shiny Colors: Song for Prism[/b] (シャニソン) is a 3D idol-training and rhythm game derived from [[idolmaster_shiny_colors]]. It is available for mobile devices and Windows through DMM Games.","[h2]Characters[/h2]","It uses the 283 Production cast indexed in [[List_of_Idolmaster_characters]].","[h2]Related tags[/h2]","* [[idolmaster]]","* [[idolmaster_shiny_colors]]","[h2]External links[/h2]","* Official site: https://shinycolors-song-for-prism.idolmaster-official.jp/"],
  "idolmaster_va-liv":["[b]vα-liv[/b] is a virtual-idol project in the [[idolmaster]] franchise launched in 2023. Its activities combine livestreaming, audience participation, music and live performance.","[h2]Characters[/h2]","* [[kamizuru_cosmo]]","* [[tomori_manaka]]","* [[letora_(idolmaster)]]","[h2]Related tags[/h2]","* [[idolmaster]]","* [[List_of_Idolmaster_characters]]","[h2]External links[/h2]","* Official portal: https://idolmaster-official.jp/va-liv"],
  "gakuen_idolmaster":["[b]Gakuen Idolmaster[/b] is a school-centered branch of [[idolmaster]] launched in 2024. The player enters the producer department of Hatsuboshi Academy and trains students from its idol department.","[h2]Characters[/h2]","See the 2024 group in [[List_of_Idolmaster_characters]].","[h2]Related tags[/h2]","* [[idolmaster]]","* [[gakuen_idolmaster_gold_rush]]","[h2]External links[/h2]","* Official site: https://gakuen.idolmaster-official.jp/"],
 }

def resolve(con, tag):
 r=con.execute('select name,category from tags where name=?',(tag,)).fetchone()
 if r:return r[0]
 for c in (tag+'_(idolmaster)', tag+'_(gakuen_idolmaster)'):
  r=con.execute('select name,category from tags where name=?',(c,)).fetchone()
  if r:return r[0]
 return None

def compact(s):
 s=s.replace('[[showtime_illusion_(idolmaster)]]','[[showtime_illusion]]')
 s=re.sub(r'\n+(\[h[1-6]\])',r'\1',s);return re.sub(r'(\[/h[1-6]\])\n+',r'\1',s)

def main():
 con=sqlite3.connect(DB); resolved={}; missing=[]
 for title,tags in GROUPS.items():
  resolved[title]=[]
  for tag in tags:
   found=resolve(con,tag)
   if found and found not in resolved[title]:resolved[title].append(found)
   elif not found:missing.append((title,tag))
 lines=["[b]The Idolmaster[/b] is a multimedia idol-raising and rhythm-game franchise created by Namco, now Bandai Namco Entertainment. The original arcade game was released on July 26, 2005 and casts the player as a producer at 765 Production who trains aspiring idols.","","As the earlier version of this article explained, the arcade game stored each player's progress on a magnetic-stripe card. Series creator Akihiro Ishihara designed its limited play sessions and persistent idols to encourage an emotional attachment between player and character. The unexpected arcade and Xbox 360 success grew into games, music, radio programs, manga, anime and live concerts performed by the voice cast.","","Most branches follow a producer and a different talent agency or school. Their casts can meet in crossover games and anniversary projects, but a tag for one branch should not automatically be added to characters or costumes from another.","[h2]Main branches in chronological order[/h2]","* [[idolmaster_(classic)]] - the 765 Production continuity begun by the 2005 arcade game; also covers [[idolmaster_1]], [[idolmaster_2]], [[idolmaster_sp]], [[idolmaster_one_for_all]], [[idolmaster_platinum_stars]] and [[idolmaster_stella_stage]].","* [[idolmaster_dearly_stars]] - 2009 Nintendo DS game centered on 876 Production.","* [[idolmaster_cinderella_girls]] - branch launched in 2011; related tags include [[idolmaster_cinderella_girls_starlight_stage]] and [[idolmaster_cinderella_girls_u149]].","* [[idolmaster_million_live!]] - branch launched in 2013 around the 765 Pro Live Theater; see [[idolmaster_million_live!_theater_days]] and [[idolmaster_million_live!_(anime)]].","* [[idolmaster_side-m]] - male-idol branch launched in 2014; see [[idolmaster_side-m_live_on_stage!]] and [[idolmaster_side-m_growing_stars]].","* [[idolmaster_shiny_colors]] - 283 Production branch launched in 2018; see [[idolmaster_shiny_colors_song_for_prism]].","* [[idolmaster_va-liv]] - virtual-idol project launched in 2023.","* [[gakuen_idolmaster]] - school-centered branch launched in 2024.","[h2]Cross-brand games[/h2]","* [[idolmaster_poplinks]]","* [[idolmaster_starlit_season]]","* [[idolmaster_tours]]","[h2]Anime and major adaptations[/h2]","* [[idolmaster_xenoglossia]] - 2007 alternate-universe mecha adaptation with a separate continuity and different voice cast.","* [[idolmaster_movie]] - film continuation of the 2011 television anime.","* [[idolmaster_cinderella_girls_u149]]","* [[idolmaster_million_live!_(anime)]]","* The Shiny Colors television anime normally uses [[idolmaster_shiny_colors]] unless a more specific established tag applies.","* [[idolmaster.kr]] - Korean live-action adaptation with an original cast.","[h2]Character index[/h2]","See [[List_of_Idolmaster_characters]] for characters grouped by the project that introduced them, in chronological branch order.","[h2]Related tags[/h2]","* [[bandai_namco_entertainment]]","* [[namco]]","[h2]External sources[/h2]","* Official franchise portal: https://idolmaster-official.jp/","* Official 20th anniversary portal: https://idolmaster-official.jp/20th_anniversary/","* Official Million Live! idol directory: https://millionlive-theaterdays.idolmaster-official.jp/idol/","* Official vα-liv portal: https://idolmaster-official.jp/va-liv"]
 list_lines=["[b]About this list:[/b]","This index groups major Idolmaster characters by the game or project in which their branch was introduced. Dates refer to the branch's debut, not every individual character's first playable appearance.","","The list uses established Gelbooru tags from the local database. It focuses on named idols and central production characters; costume variants, card names, song-specific designs and minor NPCs are excluded."]
 for title,tags in resolved.items():list_lines.append(f"[h2]{title}[/h2]"+'\n'.join(f'* [[{t}]]' for t in tags))
 list_lines += ["[h2]See also[/h2]","* [[idolmaster]]"]
 pages={'idolmaster':lines,'List_of_Idolmaster_characters':list_lines}
 pages.update(copyright_pages())
 OUT.mkdir(parents=True,exist_ok=True)
 for tag,src in pages.items():
  template='general' if tag=='List_of_Idolmaster_characters' else 'copyright'
  (OUT/f'{tag}.json').write_text(json.dumps({'tag':tag,'template':template,'source':compact('\n'.join(src)),'updated_at':datetime.now(timezone.utc).isoformat()},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print('resolved',sum(map(len,resolved.values())),'missing',missing)

if __name__=='__main__':main()
